/**
 * AccountTriggerHandler
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-04
 * @group TriggerHandler
 */

public with sharing class AccountTriggerHandler extends TriggerHandler {
    protected override void beforeInsert() {
        this.handleBefore();
    }

    protected override void beforeUpdate() {
        this.handleBefore();
    }

    protected override void afterInsert() {
        this.handleAfter();
    }

    protected override void afterUpdate() {
        this.handleAfter();
    }

    private void handleBefore() {
        Set<Id> markedAccountIds = new Set<Id>();

        for (Account account : (List<Account>) this.newList) {
            // Account marked for Azure Event creation
            if (account.Emit_Azure_Event__c == true) {
                // Reset the Emit_Azure_Event__c flag to false before insert/update
                account.Emit_Azure_Event__c = false;

                // Collect Ids for Accounts marked for Azure Event creation
                markedAccountIds.add(account.Id);
            }
        }

        // Select/Map -> Create Azure Event to be polled
        /* TODO */
    }

    private void handleAfter() {
        List<Account> accountsToUpdate = new List<Account>();

        Set<Id> accountIds = this.newMap.keySet();

        // Validate accounts against Payload configuration
        /* TODO */

        for (Account account : (List<Account>) this.newList) {
            // Set the Emit_Azure_Event__c flag to true to indicate Event creation
            if (accountIds.contains(account.Id)) {
                accountsToUpdate.add(new Account(
                    Id = account.Id,
                    Emit_Azure_Event__c = true
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}

