private void handleBefore() {
    Set<Id> markedAccountIds = new Set<Id>();

    for (Account account : (List<Account>) this.newList) {
        // Account marked for Azure Event creation
        if (account.Emit_Azure_Event__c == true) {
            // Reset the Emit_Azure_Event__c flag to false before insert/update
            account.Emit_Azure_Event__c = false;

            // Collect Ids for Accounts marked for Azure Event creation
            markedAccountIds.add(account.Id);
        }
    }

    // Create Azure Event records for marked accounts
    if (!markedAccountIds.isEmpty()) {
        AccountAzureEvent azureEvent = new AccountAzureEvent(this.newList, this.oldMap);
        List<Azure_Event__c> eventsToInsert = new List<Azure_Event__c>();

        for (Id accountId : markedAccountIds) {
            AzureEvent.EventGridDTO payload = azureEvent.getPayload(accountId);
            if (payload != null) {
                eventsToInsert.add(new Azure_Event__c(
                    SF_Record_Id__c = String.valueOf(accountId),
                    Object_Name__c = 'Account',
                    Event_Type__c = payload.eventType,
                    Payload__c = payload.toJSON()
                ));
            }
        }

        if (!eventsToInsert.isEmpty()) {
            insert eventsToInsert;
        }
    }
}

