/**
 * AccountTriggerHandlerTest
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-15
 * @group TriggerHandler
 */
@IsTest
private class AccountTriggerHandlerTest {
    @IsTest
    static void testAccountInsert_CreatesAzureEvent() {
        // Given: A new Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'CA',
            BillingPostalCode = '94105',
            BillingCountry = 'USA'
        );

        // When: Account is inserted
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Azure_Event__c should be created with proper payload
        List<Azure_Event__c> events = [
            SELECT Id, SF_Record_Id__c, Object_Name__c, Event_Type__c, Payload__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
        ];

        System.assertEquals(1, events.size(), 'Expected one Azure Event to be created');

        Azure_Event__c event = events[0];
        System.assertEquals(String.valueOf(testAccount.Id), event.SF_Record_Id__c, 'SF_Record_Id__c should match Account Id');
        System.assertEquals('Account', event.Object_Name__c, 'Object_Name__c should be Account');
        System.assertEquals('Account.Updated', event.Event_Type__c, 'Event_Type__c should be Account.Updated');
        System.assertNotEquals(null, event.Payload__c, 'Payload__c should not be null');

        // Verify payload contains expected fields
        Map<String, Object> payloadMap = (Map<String, Object>) JSON.deserializeUntyped(event.Payload__c);
        System.assert(payloadMap.containsKey('subject'), 'Payload should contain subject');
        System.assert(payloadMap.containsKey('eventType'), 'Payload should contain eventType');
        System.assert(payloadMap.containsKey('data'), 'Payload should contain data');

        Map<String, Object> dataMap = (Map<String, Object>) payloadMap.get('data');
        System.assertEquals(testAccount.Id, dataMap.get('accountId'), 'Data should contain accountId');
        System.assertEquals('Test Account', dataMap.get('accountName'), 'Data should contain accountName');
        System.assertEquals('123 Main St', dataMap.get('billingStreet'), 'Data should contain billingStreet');
        System.assertEquals('San Francisco', dataMap.get('billingCity'), 'Data should contain billingCity');
    }

    @IsTest
    static void testAccountUpdate_NameChanged_CreatesAzureEvent() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Original Name',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'CA',
            BillingPostalCode = '94105',
            BillingCountry = 'USA'
        );
        insert testAccount;

        // Delete any events from insert
        delete [SELECT Id FROM Azure_Event__c WHERE SF_Record_Id__c = :testAccount.Id];

        // When: Account name is updated
        Test.startTest();
        testAccount.Name = 'Updated Name';
        update testAccount;
        Test.stopTest();

        // Then: New Azure_Event__c should be created
        List<Azure_Event__c> events = [
            SELECT Id, SF_Record_Id__c, Event_Type__c, Payload__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
        ];

        System.assertEquals(1, events.size(), 'Expected one Azure Event to be created for name change');

        Azure_Event__c event = events[0];
        Map<String, Object> payloadMap = (Map<String, Object>) JSON.deserializeUntyped(event.Payload__c);
        Map<String, Object> dataMap = (Map<String, Object>) payloadMap.get('data');

        System.assertEquals('Updated Name', dataMap.get('accountName'), 'Payload should contain updated name');
    }

    @IsTest
    static void testAccountUpdate_NameNotChanged_NoAzureEvent() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'CA',
            BillingPostalCode = '94105',
            BillingCountry = 'USA'
        );
        insert testAccount;

        // Delete any events from insert
        delete [SELECT Id FROM Azure_Event__c WHERE SF_Record_Id__c = :testAccount.Id];

        // When: Account is updated but name is not changed
        Test.startTest();
        testAccount.BillingStreet = '456 Oak Ave';
        update testAccount;
        Test.stopTest();

        // Then: No new Azure_Event__c should be created
        List<Azure_Event__c> events = [
            SELECT Id
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
        ];

        System.assertEquals(0, events.size(), 'Expected no Azure Event when name is not changed');
    }

    @IsTest
    static void testMultipleAccounts_Insert_CreatesMultipleEvents() {
        // Given: Multiple new Accounts
        List<Account> testAccounts = new List<Account>{
            new Account(Name = 'Account 1', BillingCity = 'City 1'),
            new Account(Name = 'Account 2', BillingCity = 'City 2'),
            new Account(Name = 'Account 3', BillingCity = 'City 3')
        };

        // When: Accounts are inserted
        Test.startTest();
        insert testAccounts;
        Test.stopTest();

        // Then: Azure_Event__c records should be created for all accounts
        List<Azure_Event__c> events = [
            SELECT Id, SF_Record_Id__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c IN :new Map<Id, Account>(testAccounts).keySet()
        ];

        System.assertEquals(3, events.size(), 'Expected Azure Events for all 3 accounts');
    }

    @IsTest
    static void testMultipleAccounts_MixedUpdates_CreatesSelectiveEvents() {
        // Given: Multiple existing Accounts
        List<Account> testAccounts = new List<Account>{
            new Account(Name = 'Account 1', BillingCity = 'City 1'),
            new Account(Name = 'Account 2', BillingCity = 'City 2'),
            new Account(Name = 'Account 3', BillingCity = 'City 3')
        };
        insert testAccounts;

        // Delete events from insert
        delete [SELECT Id FROM Azure_Event__c WHERE SF_Record_Id__c IN :new Map<Id, Account>(testAccounts).keySet()];

        // When: Some accounts have name changed, others don't
        Test.startTest();
        testAccounts[0].Name = 'Updated Account 1'; // Name changed
        testAccounts[1].BillingCity = 'New City 2'; // Name NOT changed
        testAccounts[2].Name = 'Updated Account 3'; // Name changed
        update testAccounts;
        Test.stopTest();

        // Then: Only accounts with name changes should have events
        List<Azure_Event__c> events = [
            SELECT Id, SF_Record_Id__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c IN :new Map<Id, Account>(testAccounts).keySet()
        ];

        System.assertEquals(2, events.size(), 'Expected Azure Events only for accounts with name changes');

        Set<String> eventAccountIds = new Set<String>();
        for (Azure_Event__c event : events) {
            eventAccountIds.add(event.SF_Record_Id__c);
        }

        System.assert(eventAccountIds.contains(String.valueOf(testAccounts[0].Id)), 'Event should exist for Account 1');
        System.assert(!eventAccountIds.contains(String.valueOf(testAccounts[1].Id)), 'Event should NOT exist for Account 2');
        System.assert(eventAccountIds.contains(String.valueOf(testAccounts[2].Id)), 'Event should exist for Account 3');
    }

    @IsTest
    static void testPayloadStructure_ValidatesEventGridFormat() {
        // Given: A new Account with all fields populated
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'CA',
            BillingPostalCode = '94105',
            BillingCountry = 'USA'
        );

        // When: Account is inserted
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Payload should match Azure Event Grid schema
        Azure_Event__c event = [
            SELECT Payload__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
            LIMIT 1
        ];

        Map<String, Object> payload = (Map<String, Object>) JSON.deserializeUntyped(event.Payload__c);

        // Verify required Azure Event Grid fields
        System.assert(payload.containsKey('id'), 'Payload should contain id');
        System.assert(payload.containsKey('subject'), 'Payload should contain subject');
        System.assert(payload.containsKey('eventType'), 'Payload should contain eventType');
        System.assert(payload.containsKey('eventTime'), 'Payload should contain eventTime');
        System.assert(payload.containsKey('data'), 'Payload should contain data');
        System.assert(payload.containsKey('dataVersion'), 'Payload should contain dataVersion');

        // Verify subject format
        String subject = (String) payload.get('subject');
        System.assert(subject.contains('/sobjects/Account/'), 'Subject should contain /sobjects/Account/');
        System.assert(subject.contains(testAccount.Id), 'Subject should contain Account Id');

        // Verify data version
        System.assertEquals('1', payload.get('dataVersion'), 'Data version should be 1');
    }
}

