 * @group TriggerHandler
 */
@IsTest
private class AzureEventTest {
    /**
     * Mock implementation of AzureEvent for testing
     */
    private class MockAzureEvent extends AzureEvent {
        public MockAzureEvent(List<SObject> newList, Map<Id, SObject> oldMap) {
            super(newList, oldMap);
        }

        protected override Map<Id, Object> queryData() {
            Map<Id, Object> dataMap = new Map<Id, Object>();
            for (SObject record : this.newList) {
                dataMap.put(record.Id, record);
            }
            return dataMap;
        }

        protected override Map<Id, Object> validateData(Map<Id, Object> data) {
            Map<Id, Object> validatedData = new Map<Id, Object>();
            for (Id recordId : data.keySet()) {
                Account acc = (Account) data.get(recordId);
                Account oldAcc = (Account) this.oldMap?.get(recordId);

                // Validate: Name must have changed
                if (oldAcc == null || acc.Name != oldAcc.Name) {
                    validatedData.put(recordId, acc);
                }
            }
            return validatedData;
        }

        protected override String getType() {
            return MockDataProperty.class.getName();
        }

        protected override String getSubject() {
            return '/test/subject/';
        }

        protected override String getEventType() {
            return 'Test.Event';
        }
    }

    /**
     * Mock DataProperty implementation
     */
    private class MockDataProperty extends AzureEvent.DataProperty {
        @AuraEnabled
        public String testField;

        public override void mapDatum(Object validDatum) {
            Account acc = (Account) validDatum;
            this.testField = acc.Name;
        }

        public override String getVersion() {
            return '1.0';
        }
    }

    @IsTest
    static void testQueryData_ReturnsAllRecords() {
        // Given: Multiple Account records
