/**
 * AccountTriggerHandlerTest
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-15
 * @group TriggerHandler
 */
@IsTest
private class AccountTriggerHandlerTest {
    @IsTest
    static void testHandleAfter_Insert_SetsEmitFlag() {
        // Given: A new Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingCity = 'San Francisco'
        );

        // When: Account is inserted
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should be set by handleAfter
        Account updatedAccount = [
            SELECT Emit_Azure_Event__c
            FROM Account
            WHERE Id = :testAccount.Id
        ];

        // Note: Due to the two-phase pattern, the flag is first set to true, then reset to false
        // After Test.stopTest(), we should see the final state (false after being processed)
        System.assertEquals(false, updatedAccount.Emit_Azure_Event__c,
            'Flag should be false after processing');
    }

    @IsTest
    static void testHandleAfter_Update_NameChanged_SetsEmitFlag() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Original Name',
            BillingCity = 'San Francisco'
        );
        insert testAccount;

        // When: Account name is changed
        Test.startTest();
        testAccount.Name = 'Updated Name';
        update testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should have been processed
        Account updatedAccount = [
            SELECT Emit_Azure_Event__c
            FROM Account
            WHERE Id = :testAccount.Id
        ];

        System.assertEquals(false, updatedAccount.Emit_Azure_Event__c,
            'Flag should be false after processing');
    }

    @IsTest
    static void testHandleAfter_Update_NameNotChanged_DoesNotSetEmitFlag() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingCity = 'San Francisco'
        );
        insert testAccount;

        // Reset flag after insert
        testAccount.Emit_Azure_Event__c = false;
        update testAccount;

        // When: Account is updated but name is NOT changed
        Test.startTest();
        testAccount.BillingCity = 'Los Angeles';
        update testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should remain false
        Account updatedAccount = [
            SELECT Emit_Azure_Event__c
            FROM Account
            WHERE Id = :testAccount.Id
        ];

        System.assertEquals(false, updatedAccount.Emit_Azure_Event__c,
            'Flag should remain false when name not changed');
    }

    @IsTest
    static void testHandleBefore_ResetsFlagWhenTrue() {
        // Given: Account with Emit_Azure_Event__c = true
        Account testAccount = new Account(
            Name = 'Test Account',
            Emit_Azure_Event__c = true
        );

        // When: Account is inserted (handleBefore runs)
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Flag should be reset during processing
        // The two-phase pattern: afterInsert sets it to true, then beforeUpdate resets it
        Account result = [SELECT Emit_Azure_Event__c FROM Account WHERE Id = :testAccount.Id];
        System.assertEquals(false, result.Emit_Azure_Event__c,
            'Flag should be reset by handleBefore');
    }

    @IsTest
    static void testMultipleAccounts_OnlySetsEmitFlagForNameChanges() {
        // Given: Multiple accounts
        List<Account> accounts = new List<Account>{
            new Account(Name = 'Account 1'),
            new Account(Name = 'Account 2'),
            new Account(Name = 'Account 3')
        };
        insert accounts;

        // Reset flags
        for (Account acc : accounts) {
            acc.Emit_Azure_Event__c = false;
        }
        update accounts;

        // When: Only some accounts have name changed
        Test.startTest();
        accounts[0].Name = 'Updated Account 1';  // Name changed
        accounts[1].BillingCity = 'New City';    // Name NOT changed
        accounts[2].Name = 'Updated Account 3';  // Name changed
        update accounts;
        Test.stopTest();

        // Then: Only accounts with name changes should have been processed
        Map<Id, Account> updatedAccounts = new Map<Id, Account>([
            SELECT Id, Emit_Azure_Event__c
            FROM Account
            WHERE Id IN :accounts
        ]);

        // All flags should be false after processing (the two-phase pattern completes)
        for (Account acc : updatedAccounts.values()) {
            System.assertEquals(false, acc.Emit_Azure_Event__c,
                'Flag should be false after processing');
        }
    }

    @IsTest
    static void testTriggerHandler_BypassMechanism() {
        // Given: Trigger handler is bypassed
        TriggerHandler.bypass('AccountTriggerHandler');

        Account testAccount = new Account(Name = 'Test Account');

        // When: Account is inserted with bypass active
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Handler should not have run (flag remains null/false)
        Account result = [SELECT Emit_Azure_Event__c FROM Account WHERE Id = :testAccount.Id];
        System.assertEquals(false, result.Emit_Azure_Event__c,
            'Flag should remain false when handler is bypassed');

        // Cleanup
        TriggerHandler.clearBypass('AccountTriggerHandler');
    }

    @IsTest
    static void testTriggerHandler_ClearBypass() {
        // Given: Trigger handler was bypassed then cleared
        TriggerHandler.bypass('AccountTriggerHandler');
        TriggerHandler.clearBypass('AccountTriggerHandler');

        Account testAccount = new Account(Name = 'Test Account');

        // When: Account is inserted after bypass is cleared
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Handler should run normally
        Account result = [SELECT Emit_Azure_Event__c FROM Account WHERE Id = :testAccount.Id];
        // Handler ran and completed its two-phase process
        System.assertNotEquals(null, result, 'Account should exist');
    }

    @IsTest
    static void testTriggerExecutesInAllContexts() {
        // Given: An account
        Account testAccount = new Account(Name = 'Test Account');

        // When: Account goes through insert and update
        Test.startTest();
        insert testAccount;  // Tests beforeInsert, afterInsert

        testAccount.Name = 'Updated Name';
        update testAccount;  // Tests beforeUpdate, afterUpdate
        Test.stopTest();

        // Then: No errors should have occurred
        Account result = [SELECT Id, Name FROM Account WHERE Id = :testAccount.Id];
        System.assertEquals('Updated Name', result.Name, 'Account should be updated successfully');
    }
}

