            return '/test/subject/';
        }

        protected override String getEventType() {
            return 'Test.Event';
        }
    }

    /**
     * Mock DataProperty implementation
     */
    private class MockDataProperty extends AzureEvent.DataProperty {
        @AuraEnabled
        public String testField;

        public override void mapDatum(Object validDatum) {
            Account acc = (Account) validDatum;
            this.testField = acc.Name;
        }

        public override String getVersion() {
            return '1.0';
        }
    }

    @IsTest
    static void testQueryData_ReturnsAllRecords() {
        // Given: Multiple Account records
        List<Account> accounts = new List<Account>{
            new Account(Id = testUtil.generateFakeId(Account.SObjectType), Name = 'Account 1'),
            new Account(Id = testUtil.generateFakeId(Account.SObjectType), Name = 'Account 2')
        };

        // When: queryData is called
        MockAzureEvent azureEvent = new MockAzureEvent(accounts, null);
        Map<Id, Object> result = azureEvent.queryData();

        // Then: All records should be returned
        System.assertEquals(2, result.size(), 'Should return all records');
        System.assert(result.containsKey(accounts[0].Id), 'Should contain first account');
        System.assert(result.containsKey(accounts[1].Id), 'Should contain second account');
    }

    @IsTest
    static void testValidateData_Insert_ReturnsAllRecords() {
        // Given: New Account records (no oldMap)
        List<Account> accounts = new List<Account>{
            new Account(Id = testUtil.generateFakeId(Account.SObjectType), Name = 'Account 1'),
            new Account(Id = testUtil.generateFakeId(Account.SObjectType), Name = 'Account 2')
        };

        Map<Id, Object> queriedData = new Map<Id, Object>();
        for (Account acc : accounts) {
            queriedData.put(acc.Id, acc);
        }

        // When: validateData is called with no oldMap (insert scenario)
        MockAzureEvent azureEvent = new MockAzureEvent(accounts, null);
        Map<Id, Object> validatedData = azureEvent.validateData(queriedData);

        // Then: All records should be validated (inserts always valid)
        System.assertEquals(2, validatedData.size(), 'All inserts should be valid');
    }

    @IsTest
    static void testValidateData_Update_NameChanged_ReturnsChanged() {
        // Given: Updated Account with name change
        Id accountId = testUtil.generateFakeId(Account.SObjectType);
        Account oldAccount = new Account(Id = accountId, Name = 'Old Name');
        Account newAccount = new Account(Id = accountId, Name = 'New Name');

        Map<Id, SObject> oldMap = new Map<Id, SObject>{ accountId => oldAccount };
        Map<Id, Object> queriedData = new Map<Id, Object>{ accountId => newAccount };

        // When: validateData is called
        MockAzureEvent azureEvent = new MockAzureEvent(new List<Account>{ newAccount }, oldMap);
        Map<Id, Object> validatedData = azureEvent.validateData(queriedData);

        // Then: Changed record should be validated
        System.assertEquals(1, validatedData.size(), 'Changed record should be valid');
        System.assert(validatedData.containsKey(accountId), 'Should contain changed account');
    }

    @IsTest
    static void testValidateData_Update_NameNotChanged_ReturnsEmpty() {
        // Given: Updated Account with no name change
        Id accountId = testUtil.generateFakeId(Account.SObjectType);
        Account oldAccount = new Account(Id = accountId, Name = 'Same Name');
        Account newAccount = new Account(Id = accountId, Name = 'Same Name');

        Map<Id, SObject> oldMap = new Map<Id, SObject>{ accountId => oldAccount };
        Map<Id, Object> queriedData = new Map<Id, Object>{ accountId => newAccount };

        // When: validateData is called
        MockAzureEvent azureEvent = new MockAzureEvent(new List<Account>{ newAccount }, oldMap);
        Map<Id, Object> validatedData = azureEvent.validateData(queriedData);

        // Then: No records should be validated
        System.assertEquals(0, validatedData.size(), 'Unchanged record should not be valid');
    }

    @IsTest
    static void testGetPayload_ReturnsEventGridDTO() {
        // Given: Account with data
        Id accountId = testUtil.generateFakeId(Account.SObjectType);
        Account account = new Account(Id = accountId, Name = 'Test Account');

        // When: AzureEvent is created
        MockAzureEvent azureEvent = new MockAzureEvent(new List<Account>{ account }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(accountId);

        // Then: EventGridDTO should be populated correctly
        System.assertNotEquals(null, payload, 'Payload should not be null');
        System.assert(payload.subject.contains('/test/subject/'), 'Subject should match');
        System.assert(payload.subject.contains(String.valueOf(accountId)), 'Subject should contain account ID');
        System.assertEquals('Test.Event', payload.eventType, 'Event type should match');
        System.assertNotEquals(null, payload.eventTime, 'Event time should be set');
        System.assertNotEquals(null, payload.id, 'Event ID should be generated');
        System.assertEquals('1.0', payload.dataVersion, 'Data version should match');
    }

    @IsTest
    static void testEventGridDTO_ToJSON_ReplacesDataX() {
        // Given: Account with data
        Id accountId = testUtil.generateFakeId(Account.SObjectType);
        Account account = new Account(Id = accountId, Name = 'Test Account');

        // When: AzureEvent is created and JSON is generated
        MockAzureEvent azureEvent = new MockAzureEvent(new List<Account>{ account }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(accountId);
        String jsonString = payload.toJSON();

        // Then: JSON should contain 'data' field, not 'dataX'
        System.assert(jsonString.contains('"data"'), 'JSON should contain "data" field');
        System.assert(!jsonString.contains('"dataX"'), 'JSON should not contain "dataX" field');
    }

    @IsTest
    static void testDataProperty_MapDatum() {
        // Given: Account data
        Account account = new Account(Name = 'Test Account');

        // When: mapDatum is called
        MockDataProperty dataProperty = new MockDataProperty();
        dataProperty.mapDatum(account);

        // Then: Data should be mapped correctly
        System.assertEquals('Test Account', dataProperty.testField, 'Test field should be mapped');
    }

    @IsTest
    static void testDataProperty_GetVersion() {
        // Given: DataProperty instance
        MockDataProperty dataProperty = new MockDataProperty();

        // When: getVersion is called
        String version = dataProperty.getVersion();

        // Then: Version should be returned
        System.assertEquals('1.0', version, 'Version should be 1.0');
    }

    /**
     * Test utility for generating fake IDs
     */
    private class TestUtility {
        private Integer fakeIdCount = 0;

        public Id generateFakeId(Schema.SObjectType sObjectType) {
            String result = String.valueOf(fakeIdCount++);
            return (Id)(sObjectType.getDescribe().getKeyPrefix() + '0'.repeat(12-result.length()) + result);
        }
    }

    private static TestUtility testUtil = new TestUtility();
}

