/**
 * AccountAzureEventTest
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-15
 * @group TriggerHandler
 */
@IsTest
private class AccountAzureEventTest {
    @IsTest
    static void testConstructor_Insert_CreatesPayloadsForAllAccounts() {
        // Given: Accounts inserted in database
        List<Account> accounts = new List<Account>{
            new Account(
                Name = 'Test Account 1',
                BillingStreet = '123 Main St',
                BillingCity = 'San Francisco',
                BillingState = 'California',
                BillingPostalCode = '94105',
                BillingCountry = 'United States'
            ),
            new Account(
                Name = 'Test Account 2',
                BillingStreet = '456 Oak Ave',
                BillingCity = 'Los Angeles',
                BillingState = 'California',
                BillingPostalCode = '90001',
                BillingCountry = 'United States'
            )
        };
        insert accounts;

        // When: AccountAzureEvent is constructed (triggers queryData and validateData)
        AccountAzureEvent azureEvent = new AccountAzureEvent(accounts, null);

        // Then: Payloads should be created for all accounts
        AzureEvent.EventGridDTO payload1 = azureEvent.getPayload(accounts[0].Id);
        AzureEvent.EventGridDTO payload2 = azureEvent.getPayload(accounts[1].Id);

        System.assertNotEquals(null, payload1, 'Payload should be created for first account');
        System.assertNotEquals(null, payload2, 'Payload should be created for second account');
        System.assert(payload1.toJSON().contains('Test Account 1'), 'Payload should contain account name');
    }

    @IsTest
    static void testConstructor_Update_NameChanged_CreatesPayload() {
        // Given: Account with name change
        Account oldAccount = new Account(Name = 'Old Name');
        insert oldAccount;

        Account newAccount = [SELECT Id, Name, BillingAddress FROM Account WHERE Id = :oldAccount.Id];
        newAccount.Name = 'New Name';

        Map<Id, SObject> oldMap = new Map<Id, SObject>{ oldAccount.Id => oldAccount };

        // When: AccountAzureEvent is constructed with name change
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ newAccount }, oldMap);

        // Then: Payload should be created for changed account
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(newAccount.Id);
        System.assertNotEquals(null, payload, 'Payload should be created for name change');
        System.assert(payload.toJSON().contains('New Name'), 'Payload should contain new name');
    }

    @IsTest
    static void testConstructor_Update_NameNotChanged_NoPayload() {
        // Given: Account with no name change
        Account oldAccount = new Account(Name = 'Same Name', BillingCity = 'Old City');
        insert oldAccount;

        Account newAccount = [SELECT Id, Name, BillingAddress FROM Account WHERE Id = :oldAccount.Id];
        newAccount.BillingCity = 'New City';  // Only city changed, not name

        Map<Id, SObject> oldMap = new Map<Id, SObject>{ oldAccount.Id => oldAccount };

        // When: AccountAzureEvent is constructed without name change
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ newAccount }, oldMap);

        // Then: No payload should be created
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(newAccount.Id);
        System.assertEquals(null, payload, 'No payload should be created when name unchanged');
    }

    @IsTest
    static void testGetType_ReturnsAccountDataProperty() {
        // Given: AccountAzureEvent instance
        List<Account> accounts = new List<Account>{ new Account(Name = 'Test') };
        insert accounts;

        AccountAzureEvent azureEvent = new AccountAzureEvent(accounts, null);

        // When: getType is called
        String typeString = azureEvent.getType();

        // Then: Should return AccountDataProperty class name
        System.assert(typeString.contains('AccountDataProperty'), 'Should return AccountDataProperty type');
    }

    @IsTest
    static void testGetSubject_ReturnsAccountSubject() {
        // Given: AccountAzureEvent instance
        List<Account> accounts = new List<Account>{ new Account(Name = 'Test') };
        insert accounts;

        AccountAzureEvent azureEvent = new AccountAzureEvent(accounts, null);

        // When: getSubject is called
        String subject = azureEvent.getSubject();

        // Then: Should return account subject path
        System.assertEquals('/sobjects/Account/', subject, 'Should return correct subject');
    }

    @IsTest
    static void testGetEventType_ReturnsAccountUpdated() {
        // Given: AccountAzureEvent instance
        List<Account> accounts = new List<Account>{ new Account(Name = 'Test') };
        insert accounts;

        AccountAzureEvent azureEvent = new AccountAzureEvent(accounts, null);

        // When: getEventType is called
        String eventType = azureEvent.getEventType();

        // Then: Should return Account.Updated
        System.assertEquals('Account.Updated', eventType, 'Should return Account.Updated');
    }

    @IsTest
    static void testAccountDataProperty_MapDatum_AllFieldsMapped() {
        // Given: Account with all fields populated
        Account account = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'California',
            BillingPostalCode = '94105',
            BillingCountry = 'United States'
        );
        insert account;

        Account queriedAccount = [
            SELECT Id, Name, BillingAddress, Region__c, National_Account__c
            FROM Account
            WHERE Id = :account.Id
        ];

        // When: AccountDataProperty maps the account
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ queriedAccount }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(queriedAccount.Id);

        // Then: All fields should be mapped
        System.assertNotEquals(null, payload, 'Payload should be created');
        System.assertNotEquals(null, payload.dataX, 'Data property should be populated');

        // Verify JSON structure
        String jsonString = payload.toJSON();
        System.assert(jsonString.contains('"accountId"'), 'Should contain accountId');
        System.assert(jsonString.contains('"accountName"'), 'Should contain accountName');
        System.assert(jsonString.contains('Test Account'), 'Should contain account name value');
    }

    @IsTest
    static void testAccountDataProperty_MapDatum_AddressFields() {
        // Given: Account with billing address
        Account account = new Account(
            Name = 'Test Account',
            BillingStreet = '123 Main St',
            BillingCity = 'San Francisco',
            BillingState = 'California',
            BillingPostalCode = '94105',
            BillingCountry = 'United States'
        );
        insert account;

        Account queriedAccount = [
            SELECT Id, Name, BillingAddress
            FROM Account
            WHERE Id = :account.Id
        ];

        // When: AccountDataProperty maps the account
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ queriedAccount }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(queriedAccount.Id);
        String jsonString = payload.toJSON();

        // Then: Address fields should be broken down
        System.assert(jsonString.contains('"billingStreet"'), 'Should contain billingStreet');
        System.assert(jsonString.contains('"billingCity"'), 'Should contain billingCity');
        System.assert(jsonString.contains('"billingState"'), 'Should contain billingState');
        System.assert(jsonString.contains('"billingPostalCode"'), 'Should contain billingPostalCode');
        System.assert(jsonString.contains('"billingCountry"'), 'Should contain billingCountry');
        System.assert(jsonString.contains('123 Main St'), 'Should contain street value');
        System.assert(jsonString.contains('San Francisco'), 'Should contain city value');
    }

    @IsTest
    static void testAccountDataProperty_MapDatum_NullAddress() {
        // Given: Account without billing address
        Account account = new Account(Name = 'Test Account');
        insert account;

        Account queriedAccount = [
            SELECT Id, Name, BillingAddress
            FROM Account
            WHERE Id = :account.Id
        ];

        // When: AccountDataProperty maps the account
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ queriedAccount }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(queriedAccount.Id);

        // Then: Should handle null address gracefully
        System.assertNotEquals(null, payload, 'Payload should still be created');
        String jsonString = payload.toJSON();
        System.assert(jsonString.contains('Test Account'), 'Should contain account name');
    }

    @IsTest
    static void testGetPayload_ContainsAccountIdInSubject() {
        // Given: Account
        Account account = new Account(Name = 'Test Account');
        insert account;

        // When: getPayload is called
        AccountAzureEvent azureEvent = new AccountAzureEvent(new List<Account>{ account }, null);
        AzureEvent.EventGridDTO payload = azureEvent.getPayload(account.Id);

        // Then: Subject should contain account ID
        System.assert(payload.subject.contains('/sobjects/Account/'), 'Subject should have Account path');
        System.assert(payload.subject.contains(String.valueOf(account.Id)), 'Subject should contain account ID');
    }

    @IsTest
    static void testMultipleAccounts_CreatesSeparatePayloads() {
        // Given: Multiple accounts
        List<Account> accounts = new List<Account>{
            new Account(Name = 'Account 1'),
            new Account(Name = 'Account 2'),
            new Account(Name = 'Account 3')
        };
        insert accounts;

        // When: AccountAzureEvent processes them
        AccountAzureEvent azureEvent = new AccountAzureEvent(accounts, null);

        // Then: Each account should have its own payload
        for (Account acc : accounts) {
            AzureEvent.EventGridDTO payload = azureEvent.getPayload(acc.Id);
            System.assertNotEquals(null, payload, 'Payload should exist for account: ' + acc.Name);
            System.assert(payload.subject.contains(String.valueOf(acc.Id)), 'Payload should be for correct account');
        }
    }
}

